private class ModesServerNativeImpl(private val handle: Long) : ModesServerNative {
    // The read lock keeps `handle` alive for the duration of a native call; destroy()
    // takes the write lock, which waits for in-flight calls to finish. Readers do not
    // exclude each other, so independent calls on this plugin still run concurrently
    // and cancelling a subscription does not queue behind a slow blocking call.
    private val lifecycle = ReentrantReadWriteLock()
    @Volatile private var destroyed = false

    private inline fun <Value> withOpen(action: () -> Value): Value = lifecycle.read {
        check(!destroyed) { "ModesServer is closed" }
        action()
    }

    override fun setAvailableModes(modes: List<ModesServer.Mode>): Int = withOpen {
        NativeModesServer.setAvailableModes(handle, modes.map { it.toNative() }.toTypedArray())
    }

    override fun destroy() {
        lifecycle.write {
            if (destroyed) return
            destroyed = true
            NativeModesServer.destroy(handle)
        }
    }
}

internal actual fun createModesServerNative(systemHandle: Long): ModesServerNative =
    ModesServerNativeImpl(NativeModesServer.create(systemHandle))
